CREATE TABLE IF NOT EXISTS admin_identities(id CHAR(36) PRIMARY KEY,central_subject VARCHAR(160) NOT NULL UNIQUE,display_name VARCHAR(160) NOT NULL DEFAULT '',created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),last_seen_at DATETIME(3) NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS enrollment_tokens(id CHAR(36) PRIMARY KEY,token_hash CHAR(64) NOT NULL UNIQUE,created_by CHAR(36) NULL,expires_at DATETIME(3) NOT NULL,used_at DATETIME(3) NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),KEY idx_enrollment_expiry(expires_at,used_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS devices(id CHAR(36) PRIMARY KEY,device_name VARCHAR(120) NOT NULL,windows_username VARCHAR(120) NOT NULL DEFAULT '',domain_name VARCHAR(160) NOT NULL DEFAULT '',os_caption VARCHAR(160) NOT NULL DEFAULT '',os_version VARCHAR(80) NOT NULL DEFAULT '',os_build VARCHAR(80) NOT NULL DEFAULT '',manufacturer VARCHAR(120) NOT NULL DEFAULT '',model VARCHAR(160) NOT NULL DEFAULT '',cpu_name VARCHAR(180) NOT NULL DEFAULT '',ram_total_bytes BIGINT UNSIGNED NOT NULL DEFAULT 0,agent_version VARCHAR(40) NOT NULL DEFAULT '',install_mode VARCHAR(32) NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,status VARCHAR(20) NOT NULL DEFAULT 'active',policy_revision INT UNSIGNED NOT NULL DEFAULT 0,first_boot_at DATETIME(3) NULL,last_boot_at DATETIME(3) NULL,last_seen_at DATETIME(3) NULL,last_ip VARCHAR(64) NOT NULL DEFAULT '',enrolled_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),CONSTRAINT chk_device_mode CHECK(install_mode IN ('certificate','certificate-and-web')),CONSTRAINT chk_device_status CHECK(status IN ('active','disabled','revoked')),KEY idx_devices_status(status,last_seen_at),KEY idx_devices_name(device_name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS device_disks(id CHAR(36) PRIMARY KEY,device_id CHAR(36) NOT NULL,drive_letter VARCHAR(12) NOT NULL,volume_label VARCHAR(120) NOT NULL DEFAULT '',filesystem VARCHAR(40) NOT NULL DEFAULT '',media_type VARCHAR(40) NOT NULL DEFAULT '',total_bytes BIGINT UNSIGNED NOT NULL DEFAULT 0,free_bytes BIGINT UNSIGNED NOT NULL DEFAULT 0,used_percent DECIMAL(5,2) NOT NULL DEFAULT 0,smart_health VARCHAR(40) NOT NULL DEFAULT 'unknown',temperature_c DECIMAL(5,2) NULL,collected_at DATETIME(3) NOT NULL,UNIQUE KEY uq_device_drive(device_id,drive_letter),CONSTRAINT fk_disk_device FOREIGN KEY(device_id) REFERENCES devices(id) ON DELETE CASCADE,KEY idx_disk_usage(used_percent,collected_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS telemetry_snapshots(id CHAR(36) PRIMARY KEY,device_id CHAR(36) NOT NULL,cpu_percent DECIMAL(5,2) NULL,memory_used_bytes BIGINT UNSIGNED NULL,memory_total_bytes BIGINT UNSIGNED NULL,uptime_seconds BIGINT UNSIGNED NULL,boot_at DATETIME(3) NULL,network JSON NOT NULL,snapshot JSON NOT NULL,collected_at DATETIME(3) NOT NULL,CONSTRAINT fk_telemetry_device FOREIGN KEY(device_id) REFERENCES devices(id) ON DELETE CASCADE,KEY idx_telemetry_device_time(device_id,collected_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS installed_certificates(id CHAR(36) PRIMARY KEY,device_id CHAR(36) NOT NULL,subject_name VARCHAR(512) NOT NULL DEFAULT '',issuer_name VARCHAR(512) NOT NULL DEFAULT '',serial_number VARCHAR(160) NOT NULL DEFAULT '',thumbprint_sha1 CHAR(40) NOT NULL DEFAULT '',thumbprint_sha256 CHAR(64) NOT NULL DEFAULT '',not_before DATETIME(3) NULL,not_after DATETIME(3) NULL,store_name VARCHAR(100) NOT NULL DEFAULT '',has_private_key TINYINT(1) NOT NULL DEFAULT 0,observed_at DATETIME(3) NOT NULL,UNIQUE KEY uq_cert_device_thumb(device_id,thumbprint_sha1,store_name),CONSTRAINT fk_cert_device FOREIGN KEY(device_id) REFERENCES devices(id) ON DELETE CASCADE,KEY idx_cert_expiry(not_after)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS web_rules(id CHAR(36) PRIMARY KEY,name VARCHAR(120) NOT NULL,hostname VARCHAR(253) NOT NULL,action VARCHAR(20) NOT NULL,scope_type VARCHAR(30) NOT NULL DEFAULT 'all',scope_value VARCHAR(160) NOT NULL DEFAULT '',enabled TINYINT(1) NOT NULL DEFAULT 1,created_by CHAR(36) NULL,updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),CONSTRAINT chk_web_action CHECK(action IN ('allow','block')),KEY idx_web_rule_enabled(enabled,hostname)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS certificate_site_rules(id CHAR(36) PRIMARY KEY,name VARCHAR(120) NOT NULL,hostname VARCHAR(253) NOT NULL,certificate_scope VARCHAR(120) NOT NULL DEFAULT 'managed',enabled TINYINT(1) NOT NULL DEFAULT 1,created_by CHAR(36) NULL,updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),KEY idx_cert_rule_enabled(enabled,hostname)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS policies(revision INT UNSIGNED PRIMARY KEY,status VARCHAR(20) NOT NULL,payload JSON NOT NULL,signature TEXT NOT NULL,created_by CHAR(36) NULL,published_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),CONSTRAINT chk_policy_status CHECK(status IN ('published','revoked'))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS device_events(id CHAR(36) PRIMARY KEY,device_id CHAR(36) NULL,event_type VARCHAR(80) NOT NULL,severity VARCHAR(20) NOT NULL DEFAULT 'info',title VARCHAR(160) NOT NULL,message VARCHAR(1200) NOT NULL DEFAULT '',details JSON NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),CONSTRAINT fk_event_device FOREIGN KEY(device_id) REFERENCES devices(id) ON DELETE SET NULL,KEY idx_events_created(created_at),KEY idx_events_severity(severity,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS browsing_events(id CHAR(36) PRIMARY KEY,device_id CHAR(36) NOT NULL,hostname VARCHAR(253) NOT NULL,decision VARCHAR(20) NOT NULL,policy_revision INT UNSIGNED NOT NULL DEFAULT 0,rule_name VARCHAR(160) NOT NULL DEFAULT '',occurred_at DATETIME(3) NOT NULL,CONSTRAINT fk_browse_device FOREIGN KEY(device_id) REFERENCES devices(id) ON DELETE CASCADE,KEY idx_browse_time(occurred_at),KEY idx_browse_domain(hostname,occurred_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS uninstall_requests(id CHAR(36) PRIMARY KEY,device_id CHAR(36) NOT NULL,request_reason VARCHAR(1000) NOT NULL,requested_by VARCHAR(160) NOT NULL DEFAULT '',status VARCHAR(20) NOT NULL DEFAULT 'pending',requested_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),reviewed_by CHAR(36) NULL,reviewed_at DATETIME(3) NULL,release_token_hash CHAR(64) NULL,release_expires_at DATETIME(3) NULL,CONSTRAINT fk_uninstall_device FOREIGN KEY(device_id) REFERENCES devices(id) ON DELETE CASCADE,KEY idx_uninstall_status(status,requested_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS agent_settings(setting_key VARCHAR(100) PRIMARY KEY,setting_value JSON NOT NULL,updated_by CHAR(36) NULL,updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS mail_integrations(id CHAR(36) PRIMARY KEY,provider VARCHAR(40) NOT NULL,mailbox VARCHAR(254) NOT NULL,display_name VARCHAR(160) NOT NULL DEFAULT '',status VARCHAR(30) NOT NULL DEFAULT 'pending',scopes JSON NOT NULL,secret_reference VARCHAR(255) NOT NULL DEFAULT '',last_sync_at DATETIME(3) NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE KEY uq_mailbox_provider(provider,mailbox)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS alert_deliveries(id CHAR(36) PRIMARY KEY,event_id CHAR(36) NULL,channel VARCHAR(20) NOT NULL,destination VARCHAR(254) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'queued',attempts INT UNSIGNED NOT NULL DEFAULT 0,last_error VARCHAR(1000) NOT NULL DEFAULT '',created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),sent_at DATETIME(3) NULL,KEY idx_alert_status(status,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS agent_policy_lock(id TINYINT UNSIGNED PRIMARY KEY) ENGINE=InnoDB;
INSERT IGNORE INTO agent_policy_lock(id) VALUES(1);
